-- Generated by model/lib/sql/generate.mjs. Loads Growth Bonus Threshold IN from cells/Growth Bonus Threshold IN.csv in the folder of input cells. Two rows for one cell add up.
INSERT INTO "Growth Bonus Threshold IN" ("Customer Group", "Versions", "Years", v, ver, is_deleted) SELECT coalesce(k0."Customer Group", throwIf(isNull(k0."Customer Group"), 'cells name a member Customer Group does not have')), coalesce(k1."Versions", throwIf(isNull(k1."Versions"), 'cells name a member Versions does not have')), coalesce(k2."Years", throwIf(isNull(k2."Years"), 'cells name a member Years does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/Growth Bonus Threshold IN.csv', 'CSVWithNames', '"Customer Group" String, "Versions" String, "Years" String, "value" String') c LEFT JOIN "dim Customer Group" k0 ON k0.name = c."Customer Group" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY ALL;
